def split_csv(line):
    """Parse one line of CSV and return fields as a list of strings.

    Returns None if the line is malformed.
    """
    fields = []
    i = 0

    while i < len(line):
        # Start of a field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or closing quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(''.join(field))
                        # Skip the comma if present
                        if i < len(line) and line[i] == ',':
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))
            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

